import { startOfToday } from 'date-fns';

/** Returns the value represented as ISO string */
export function getSimplifiedExtendedISOStringFromValue(
  value: Date | number | string | null,
  microNanoSeconds?: number,
): string | null {
  if (typeof value === 'number') {
    const dateValue = new Date(value);
    return microNanoSeconds
      ? _applyInitialTime(dateValue, null, microNanoSeconds.toString())
      : dateValue.toISOString();
  }

  if (value instanceof Date) {
    return microNanoSeconds
      ? _applyInitialTime(value, null, microNanoSeconds.toString())
      : value.toISOString();
  }

  return value;
}

/** Get formatted date. */
function getISOFormattedDate(date: Date): string {
  return `${date.getFullYear()}-${valueTo2DigitString(
    date.getMonth() + 1,
  )}-${valueTo2DigitString(date.getDate())}`;
}

/** Get formatted time. */
function getISOFormattedTime(date: Date): string {
  return `${valueTo2DigitString(date.getHours())}:${valueTo2DigitString(
    date.getMinutes(),
  )}:${valueTo2DigitString(date.getSeconds())}`;
}

/** Get the formatted localized date/time. */
export function getFormattedDateTime(date: Date): string {
  return `${getISOFormattedDate(date)} ${getISOFormattedTime(date)}`;
}

/**
 * Get milli-/micro-/nanoseconds string from string.
 * @internal
 */
export function _getSecondFractions(searchString: string | null): string {
  return searchString ? searchString.split('.')[1].replace('Z', '') : '';
}

/**
 * Format a number with max two digits to always display two digits
 * (with a leading 0 in case it is a single digit or convert it to string otherwise).
 */
function valueTo2DigitString(value: number): string {
  return `${value}`.padStart(2, '0');
}

/**
 * Replace the milli/micro/nano seconds part.
 * @returns Simplified extended ISO string
 */
function replaceSecondFractions(
  /** Date-time-string in simplified extended ISO format (Zulu time) */
  searchString: string,
  /** Fractions of a second, without ending 'Z' */
  milliMicroNanoSeconds?: string | null,
): string {
  if (milliMicroNanoSeconds) {
    return `${searchString.replace(
      searchString.split('.')[1],
      milliMicroNanoSeconds,
    )}Z`;
  }
  return searchString;
}

/** Get time part from iso string. */
function getTimeFromISOString(isoDate: string | null): string {
  return isoDate ? isoDate.split('T')[1].replace('Z', '') : '';
}

/**
 * Replace time of given ISO date string with given time
 * @internal
 */
export function _applyInitialTime(
  date: Date,
  originalDate: Date | null,
  time: string = getTimeFromISOString(startOfToday().toISOString()).split(
    '.',
  )[1],
): string {
  /*
  Depending on the timezone the user is in, when converting the selected date to an ISO string, the day might differ
  e.g.: selected date, timezone Vienna/Austria: 2021-01-01T00:00:00.000Z = ISO 2020-12-31T23:00:00.000Z
  So just replacing the fractions doesn't work, we first have to set the correct time on the date object and only afterwards
  convert it to an ISO string. This way, we have the correct date and can then just replace the fractions with what we initially
  get from the user to keep the precision for the datepicker output
   */
  if (originalDate) {
    date.setHours(originalDate.getHours());
    date.setMinutes(originalDate.getMinutes());
    date.setSeconds(originalDate.getSeconds());
  }
  return replaceSecondFractions(date.toISOString(), time);
}
